# (feastDate, name, tradition, description, patronOf) - Orthodox calendar, January to June
O = "orthodox"

DATA = [
    ("January 1", "Saint Basil the Great", O, "Archbishop of Caesarea (c. 330-379) and one of the Three Hierarchs. He wrote the Divine Liturgy that bears his name, founded hospitals for the poor and defended the faith of Nicaea.", "Hospitals, monks, the poor"),
    ("January 3", "The Holy Prophet Malachi", O, "The last prophet of the Old Testament, who foretold the coming of the messenger who would prepare the way of the Lord and the pure offering that would be made among all nations.", "Those who await the coming of Christ"),
    ("January 4", "The Synaxis of the Seventy Apostles", O, "The Church honours together the seventy disciples sent out by Christ in pairs to proclaim the Gospel, among them Barnabas, Silas and Apollos.", "Missionaries, evangelists"),
    ("January 5", "Venerable Syncletica of Alexandria", O, "Egyptian ascetic of the fourth century who gave away her wealth to live in a tomb and teach women the monastic life. Her sayings on humility and watchfulness are preserved among the Desert Mothers.", "Nuns, spiritual mothers"),
    ("January 6", "The Holy Theophany of Our Lord", "all", "The baptism of Jesus in the Jordan reveals the Holy Trinity: the Father's voice, the Son in the water, the Spirit descending as a dove. Waters are blessed on this feast across the Orthodox world.", "Catechumens, the baptised"),
    ("January 7", "The Synaxis of Saint John the Baptist", O, "The day after Theophany the Church honours John the Forerunner, who baptised Jesus. He is called the greatest born of women and the model of repentance.", "Those who prepare the way of the Lord"),
    ("January 8", "Venerable George the Chozebite", O, "Cypriot-born monk (d. c. 625) who lived in the Judean desert at the monastery of Choziba, known for humility and compassion. He cared for pilgrims and for the poor.", "Monks, pilgrims"),
    ("January 9", "Martyr Polyeuctus of Melitene", O, "Roman soldier in Armenia who tore down idols after his baptism and was beheaded around 259. His friend Nearchus encouraged him to confess Christ.", "Soldiers, new believers"),
    ("January 10", "Saint Gregory of Nyssa", O, "Brother of Saint Basil (c. 335-395) and a great theologian of the Trinity, the soul and prayer. His writings are especially valued in Orthodox spirituality.", "Theologians, those who pray"),
    ("January 11", "Venerable Theodosius the Cenobiarch", O, "Cappadocian monk (423-529) who founded a great monastery near Bethlehem and organised monastic life into communities. He is the father of communal monasticism in Palestine.", "Monks, community life"),
    ("January 12", "Martyr Tatiana of Rome", O, "A deaconess and martyr of the third century, remembered for her fearless confession of Christ before the Roman authorities. Moscow State University celebrates her feast as its patronal day.", "Students, young women"),
    ("January 13", "Martyrs Hermylus and Stratonicus", O, "A deacon and his servant martyred at Singidunum (modern Belgrade) during the persecution of Licinius. They are honoured for their courage in the face of death.", "Deacons, servants"),
    ("January 16", "The Veneration of the Chains of Saint Peter", O, "The Church venerates the chains with which Saint Peter was bound in Jerusalem and Rome. They recall Peter's imprisonment and his freedom through the angel and the prayer of the Church.", "Prisoners, those who pray for the persecuted"),
    ("January 18", "Saints Athanasius and Cyril of Alexandria", O, "Two great archbishops of Alexandria. Athanasius defended the divinity of Christ against Arius, and Cyril defended the title Theotokos for Mary at Ephesus.", "Defenders of the faith, theologians"),
    ("January 19", "Venerable Macarius the Great", O, "Egyptian desert father (c. 300-391) who lived for decades in the Scetis desert, known for compassion and for the Spiritual Homilies attributed to him.", "Hermits, those who seek prayer of the heart"),
    ("January 23", "Hieromartyr Clement of Ancyra", O, "Bishop of Ancyra who suffered torture and was martyred under Diocletian after long imprisonment. The Church honours his steadfast confession.", "Bishops, the persecuted"),
    ("January 24", "Venerable Xenia of Rome", O, "A Roman noblewoman of the fifth century who fled an arranged marriage and entered monastic life in Asia Minor, devoting herself to prayer, fasting and care for the poor.", "Women who seek the monastic life"),
    ("January 25", "Saint Gregory the Theologian", O, "Archbishop of Constantinople (329-390) and one of the Three Hierarchs. His five Theological Orations on the Trinity earned him the title 'the Theologian'.", "Theologians, poets, preachers"),
    ("January 26", "Venerable Xenophon and His Family", O, "A Byzantine senator and his wife Mary and sons John and Arcadius, who gave their wealth to the poor and dedicated their lives to God in monastic life.", "Families, those who give up wealth"),
    ("January 27", "The Translation of the Relics of Saint John Chrysostom", O, "The relics of the 'golden-mouthed' archbishop were brought back to Constantinople in 438, thirty years after his death in exile, and the people received them with honour.", "Preachers, those unjustly exiled"),
    ("January 28", "Venerable Ephraim the Syrian", O, "Deacon and teacher (c. 306-373) of Edessa, who wrote hymns and commentaries and composed the Lenten prayer 'O Lord and Master of my life'. He is a Doctor of the Church in the West.", "Deacons, hymn writers, those in Lent"),
    ("January 29", "The Translation of the Relics of Saint Ignatius the God-bearer", O, "The relics of Ignatius, bishop of Antioch, who died as a martyr in Rome around 107, were brought back to Antioch and honoured by the faithful.", "Bishops, martyrs"),
    ("January 30", "The Three Holy Hierarchs", O, "The Church honours together Basil the Great, Gregory the Theologian and John Chrysostom, three bishops of the fourth century who together shaped Christian teaching and are patrons of Christian education.", "Teachers, students, Christian education"),
    ("January 31", "Holy Unmercenaries Cyrus and John", O, "A physician from Alexandria and a former soldier who served the sick without charge and were martyred around 311. They are invoked for healing.", "Physicians, the sick"),

    ("February 1", "Martyr Tryphon", O, "A young man of Phrygia (d. c. 250) who prayed for the sick and the possessed and was beheaded under Decius. He is invoked as protector of gardens and farms.", "Gardeners, farmers"),
    ("February 3", "Righteous Symeon and Anna the Prophetess", O, "The elderly pair who greeted the child Jesus in the Temple. Simeon took him in his arms and blessed God, and Anna, a widow of eighty-four, spoke of him to all who awaited redemption.", "The elderly, those who wait faithfully"),
    ("February 4", "Venerable Isidore of Pelusium", O, "Egyptian monk and teacher (d. c. 435) whose thousands of letters gave wise guidance on Scripture, virtue and church life. He was a disciple of Saint John Chrysostom.", "Letter writers, spiritual teachers"),
    ("February 7", "Venerable Parthenius of Lampsakos", O, "Bishop of Lampsakos on the Hellespont in the fourth century, a man who prayed constantly and cared for the poor, and was known as a wonder-worker.", "Pastors, the poor"),
    ("February 8", "Great Martyr Theodore Stratelates", O, "Roman general of Heraclea martyred around 319 for refusing to sacrifice to idols. Tradition says he slew a dragon that terrorised the town, a symbol of overcoming evil.", "Soldiers, warriors for Christ"),
    ("February 10", "Hieromartyr Haralambos", O, "Bishop of Magnesia in Asia Minor who was martyred around 202 at the age of 113, after healing many and teaching the faith. His relics are venerated at Meteora.", "Healers, farmers"),
    ("February 11", "Hieromartyr Blaise of Sebaste", O, "Physician and bishop of Sebaste in Armenia, martyred around 316. He is invoked for healing of the throat, and many Churches bless throats on his feast.", "Physicians, those with throat ailments"),
    ("February 15", "The Apostle Onesimus", O, "The runaway slave of Philemon whom Paul led to faith in Christ and sent back as 'a beloved brother'. Tradition says he became a bishop and was martyred.", "Those who seek reconciliation, slaves"),
    ("February 17", "Great Martyr Theodore the Recruit", O, "A young soldier of Amasea martyred around 306 after setting fire to a pagan temple. In Greek tradition the first Saturday of Lent is his, in memory of the boiled wheat he is said to have provided.", "Soldiers, recruits"),
    ("February 18", "Pope Saint Leo the Great", O, "Pope of Rome (d. 461) whose Tome clarified the two natures of Christ at the Council of Chalcedon. The Orthodox Church honours him as a defender of the faith.", "Popes, those who seek unity"),
    ("February 19", "The Apostle Archippus", O, "One of the Seventy, a fellow soldier of Paul who served the church in Colossae. Paul urged him to complete the ministry he had received in the Lord.", "Those who serve the Church"),
    ("February 20", "Saint Leo of Catania", O, "Bishop of Catania in Sicily (d. c. 787) who was known for charity, healing and courage against sorcery. He was greatly loved by his people.", "Sicily, bishops"),
    ("February 21", "Saint Timothy of Symbola", O, "Bithynian monk of the eighth century who lived in great austerity at Symbola and was famed for wonderworking. He served as spiritual guide to many.", "Monastics, spiritual seekers"),
    ("February 22", "The Finding of the Relics of the Martyrs at Eugenius", O, "The commemoration of the discovery of the relics of a group of martyrs in Constantinople, remembered each year as a witness to the courage of the early Church.", "Martyrs, the persecuted"),
    ("February 25", "Saint Tarasius of Constantinople", O, "Patriarch of Constantinople (730-806) who presided over the Second Council of Nicaea in 787, which restored the veneration of holy icons.", "Defenders of icons, iconographers"),
    ("February 28", "Venerable Basil the Confessor", O, "Byzantine monk of the eighth century who was beaten and exiled for defending the veneration of icons during the iconoclast persecution.", "Confessors, defenders of icons"),
    ("February 29", "Venerable John Cassian the Roman", O, "Monk and writer (c. 360-435) who learned the monastic life in Egypt and carried its teaching to Gaul. His Conferences and Institutes shaped Western monasticism.", "Monks, spiritual writers"),

    ("March 1", "Martyr Eudocia of Heliopolis", O, "A woman of Lebanon who had lived in luxury, converted after reading the Gospel and became a Christian. She was martyred in the second century.", "Converts, repentant sinners"),
    ("March 2", "Hieromartyr Theodotus of Cyrene", O, "Bishop of Cyrene martyred under Licinius in the fourth century, said to have confessed Christ with courage and been put to the sword.", "Bishops, martyrs"),
    ("March 3", "Martyrs Eutropius, Cleonicus and Basiliscus", O, "Three companions of Saint Theodore the Recruit, put to death in the early fourth century at Amasea for refusing to deny Christ.", "Soldiers, martyrs"),
    ("March 4", "Venerable Gerasimus of the Jordan", O, "Monk (d. c. 475) who founded a lavra near the Jordan River. A well-known story tells of a lion that served him after he removed a thorn from its paw.", "Hermits, those who help animals"),
    ("March 5", "Martyr Conon of Isauria", O, "A gardener of Isauria in Asia Minor who was martyred in the third century. He was known for hospitality and simple faith.", "Gardeners, the humble"),
    ("March 6", "The Forty-Two Martyrs of Amorion", O, "Byzantine officers captured when Amorion fell to the Arabs in 838. After seven years of captivity they were killed for refusing to renounce Christ.", "Soldiers, prisoners of war"),
    ("March 8", "Saint Theophylact of Nicomedia", O, "Bishop of Nicomedia (d. c. 840), a confessor under the iconoclast emperors, who suffered exile and showed gentleness to all.", "Confessors, defenders of icons"),
    ("March 9", "The Forty Martyrs of Sebaste", "catholic,orthodox", "Forty Roman soldiers who in 320 refused to renounce Christ and were left on a frozen lake. One yielded, but a guard took his place and confessed the faith. All forty won the crown.", "Soldiers, the persecuted"),
    ("March 10", "Martyr Quadratus of Corinth", O, "Third-century martyr of Corinth, honoured with his companions for steadfast faith under persecution by Decius.", "Martyrs, confessors"),
    ("March 11", "Saint Sophronius of Jerusalem", O, "Patriarch of Jerusalem (c. 560-638) who defended the truth about Christ's two wills and surrendered the city to the caliph Umar with dignity and care for the faithful.", "Jerusalem, defenders of the faith"),
    ("March 12", "Saint Theophanes the Confessor", O, "Byzantine monk and chronicler (c. 758-818) who founded a monastery, defended the icons and died in exile. His Chronographia preserved the history of his age.", "Historians, defenders of icons"),
    ("March 14", "Venerable Benedict of Nursia", O, "Italian abbot (c. 480-547) who wrote the Rule that bears his name and founded Monte Cassino. The Orthodox Church honours him as a father of monastic life in the West.", "Monks, Europe"),
    ("March 15", "Martyr Agapius of Caesarea", O, "Martyr of Caesarea in Palestine who was condemned to wild beasts and, after surviving, was drowned in the sea in 306.", "The persecuted"),
    ("March 16", "Martyr Sabinus of Hermopolis", O, "Egyptian Christian martyred around 287 by drowning in the Nile after refusing to sacrifice to idols.", "Martyrs, those who suffer for Christ"),
    ("March 20", "The Venerable Fathers Martyred at the Monastery of Saint Sabbas", O, "Twenty monks of Mar Saba who were killed by raiders in 797 and are honoured among the monastery's martyrs.", "Monks, the persecuted"),
    ("March 21", "Venerable James the Confessor", O, "Bishop of Catania in Sicily and a confessor in the eighth century, who endured imprisonment and exile for the truth of the icons.", "Confessors, defenders of icons"),
    ("March 22", "Hieromartyr Basil of Ancyra", O, "Priest of Ancyra who encouraged Christians during the reign of Julian the Apostate and was martyred in 362.", "Priests, the persecuted"),
    ("March 23", "Martyr Nikon and His 199 Disciples", O, "A Roman officer turned Christian who led a group of disciples to Sicily, where they were martyred in the third century.", "Soldiers, disciples"),
    ("March 26", "The Synaxis of the Archangel Gabriel", O, "The day after the Annunciation the Church honours Gabriel, the angel who announced to Mary that she would bear the Son of God.", "Messengers, those who announce good news"),
    ("March 27", "Martyr Matrona of Thessalonica", O, "A slave woman of a Jewish household in Thessalonica who secretly prayed in church and was beaten to death by her mistress in the fourth century.", "Servants, the abused"),
    ("March 28", "Venerable Hilarion the New", O, "Bulgarian-born monk and abbot (d. 845) who defended icons under the iconoclast emperors and founded a monastery on the Bosphorus.", "Monks, defenders of icons"),

    ("April 2", "Venerable Titus the Wonderworker", O, "Byzantine monk (d. 1088) of the Venerable Titus monastery on the Black Sea, known for wonderworking and quiet life.", "Monks, those who seek peace"),
    ("April 3", "Venerable Nikita the Confessor", O, "Abbot of the monastery of Medikion in Bithynia (d. 824) who endured exile and beatings for defending the holy icons.", "Confessors, defenders of icons"),
    ("April 4", "Venerable Joseph the Hymnographer", O, "Sicilian-born hymn writer (c. 816-886) who wrote hundreds of canons for the feasts and saints of the Orthodox year. He suffered captivity and exile for the veneration of icons.", "Hymn writers, church musicians"),
    ("April 6", "Saint Eutychius of Constantinople", O, "Patriarch of Constantinople (c. 512-582) who endured exile for opposing an emperor's error and was restored to his flock at the end of his life.", "Patriarchs, the unjustly exiled"),
    ("April 7", "Venerable George of Mytilene", O, "Bishop of Mytilene on the island of Lesbos (d. c. 820), a confessor against iconoclasm who was known for wonders and humility.", "Bishops, confessors"),
    ("April 8", "The Apostles Herodion, Agabus and Rufus of the Seventy", O, "Three of the Seventy mentioned in the New Testament. Agabus foretold Paul's imprisonment, Herodion was Paul's kinsman, and Rufus was a mother's son in Rome.", "Prophets, missionaries"),
    ("April 9", "Martyr Eupsychius of Caesarea", O, "Young man of Caesarea in Cappadocia martyred in 362 under Julian the Apostate, after destroying a pagan temple.", "Young people, the persecuted"),
    ("April 10", "Martyr Terence and His Companions", O, "A group of Christians martyred at Carthage in the third century, including Terence, Africanus and Pompeius.", "North African martyrs"),
    ("April 11", "Hieromartyr Antipas of Pergamum", O, "Bishop of Pergamum, called 'my faithful witness' in the Book of Revelation, martyred at the end of the first century. He is invoked for healing of toothache.", "Bishops, the persecuted"),
    ("April 12", "Saint Basil the Confessor of Parium", O, "Bishop of Parium on the Hellespont (d. c. 750) who defended icons under the iconoclast emperor Leo III and died in exile.", "Confessors"),
    ("April 15", "The Apostles Aristarchus, Pudens and Trophimus", O, "Three disciples of Saint Paul who served the early Church. Aristarchus travelled with Paul, and Trophimus was his companion from Ephesus.", "Missionary companions"),
    ("April 15", "Martyrs Basilissa and Anastasia of Rome", O, "Two Roman noblewomen who buried martyrs' bodies and were put to death under Nero. They are remembered for their devotion to the apostles' memory.", "Noblewomen, those who bury the dead"),
    ("April 16", "Martyrs Agape, Irene and Chione", O, "Three sisters of Thessalonica martyred in 304 under Diocletian for refusing to give up the Scriptures and the faith.", "Sisters, those who protect Scripture"),
    ("April 17", "Saint Simeon the Persian", O, "Bishop of Seleucia-Ctesiphon martyred in 341 with thousands of Christians during Shapur II's persecution in Persia.", "Persia, Christians under persecution"),
    ("April 18", "Venerable John, Disciple of Saint Gregory the Decapolite", O, "Monk of the ninth century who followed the holy elder Gregory in Constantinople and was known for gentleness and prayer.", "Monks, disciples"),
    ("April 19", "Hieromartyr Paphnutius of Jerusalem", O, "Bishop of Jerusalem who suffered in the persecution of Diocletian and is remembered for his steadfast faith.", "Bishops, the persecuted"),
    ("April 20", "Venerable Theodore Trichinas", O, "Byzantine ascetic (d. c. 600), called 'the hair-shirted', who wore a hair garment and lived in constant prayer near Constantinople.", "Ascetics, those who fast"),
    ("April 22", "Venerable Theodore of Sykeon", O, "Bishop of Anastasiopolis in Galatia (d. 613) who walked to Jerusalem as a young man and later served his diocese with tireless care for the poor.", "Bishops, pilgrims"),
    ("April 24", "Great Martyr Sabbas Stratelates", O, "Gothic soldier in the Roman army who was martyred in 272 after choosing Christ. He was drowned in a river.", "Soldiers, Goths"),
    ("April 26", "Hieromartyr Basil of Amasea", O, "Bishop of Amasea who was beheaded under Licinius around 322 for refusing to hand over the Christians in his care.", "Bishops"),
    ("April 27", "Hieromartyr Simeon, Kinsman of the Lord", O, "Second bishop of Jerusalem, a cousin of Jesus, who led the Church for decades and was martyred around 107 at the age of 120.", "Jerusalem, relatives of the Lord"),
    ("April 28", "The Apostles Jason and Sosipater of the Seventy", O, "Kinsmen of Paul who preached in Greece and Corfu. Jason hosted Paul in Thessalonica, and both were arrested for the faith.", "Hosts, missionaries"),
    ("April 29", "The Nine Martyrs of Cyzicus", O, "Nine Christians of Cyzicus on the Sea of Marmara who were martyred during the persecution of Diocletian for refusing to renounce Christ.", "Martyrs of Asia Minor"),
    ("April 30", "The Holy Apostle James, Son of Zebedee", O, "Brother of John and one of the first disciples, who was beheaded by Herod Agrippa around 44, the first apostle to die as a martyr.", "Pilgrims, fishermen"),

    ("May 1", "The Holy Prophet Jeremiah", O, "A prophet of Judah who warned of exile and wept over Jerusalem. He foretold a new covenant written on hearts, which Christians see fulfilled in Christ.", "Those who weep for the world"),
    ("May 3", "Martyrs Timothy and Maura", O, "A married couple of Egypt who were tortured under Diocletian in 286 and died by crucifixion after encouraging each other for nine days.", "Married couples, those who suffer together"),
    ("May 4", "Martyr Pelagia of Tarsus", O, "A young virgin of Tarsus martyred around 304 after refusing to marry the emperor's son because she had given herself to Christ.", "Young women"),
    ("May 5", "Great Martyr Irene", O, "A young woman of Macedonia whose name means 'peace', martyred in the first century after converting many to Christ. She is invoked for peace.", "Peace, those who suffer injustice"),
    ("May 6", "The Righteous Job the Long-Suffering", O, "The man of Uz who lost everything yet blessed God, holding to hope that his Redeemer lives. The Church honours his patience and trust in the Lord.", "The suffering, those who endure loss"),
    ("May 7", "The Appearance of the Sign of the Cross at Jerusalem", O, "In 351 a shining cross appeared over Golgotha and extended to the Mount of Olives, seen by the people of Jerusalem, a sign celebrated by Saint Cyril.", "Jerusalem, Christians"),
    ("May 8", "The Holy Apostle and Evangelist John the Theologian", O, "The beloved disciple who rested on Jesus' breast and stood at the cross. He wrote the fourth Gospel, three letters and the Book of Revelation, and lived to an old age in Ephesus.", "Theologians, writers, those who love Christ"),
    ("May 9", "The Holy Prophet Isaiah", O, "The great prophet of Judah who saw the Lord on a high throne and foretold the Virgin who would conceive and bear Emmanuel. His book is read widely in Advent.", "Prophets, those who hope for the Messiah"),
    ("May 10", "The Holy Apostle Simon the Zealot", O, "One of the twelve apostles, who preached in Egypt and Britain according to tradition. He was martyred for his faith after a long ministry.", "Zealots for Christ, converts"),
    ("May 11", "Saints Cyril and Methodius, Equals of the Apostles", O, "Brothers from Thessalonica (ninth century) who created the Slavic alphabet and translated the Scriptures and liturgy into Slavonic, bringing Christ to the Slavs.", "The Slavs, translators, teachers"),
    ("May 13", "Martyr Glyceria of Heraclea", O, "A young Roman woman who was killed in Heraclea around 177 after refusing to sacrifice to idols. She confessed Christ before the governor.", "Young women, martyrs"),
    ("May 14", "Martyr Isidore of Chios", O, "A Roman soldier of Alexandria who was martyred on the island of Chios around 251 for confessing Christ before the governor.", "Soldiers, Chios"),
    ("May 15", "Venerable Pachomius the Great", O, "Egyptian founder of communal monasticism (c. 292-348) who gathered monks into organised communities with a rule of prayer and work.", "Monks, community life"),
    ("May 16", "Venerable Theodore the Sanctified", O, "Disciple and successor of Pachomius (c. 314-368) who led the Egyptian communities after the founder's death. He was known for firmness and gentleness.", "Abbots, monastic leaders"),
    ("May 17", "The Apostles Andronicus and Junia", O, "A pair of early Christians whom Paul calls 'kinsmen who were in prison with me' and 'of note among the apostles'. They are remembered as early missionaries.", "Missionary couples"),
    ("May 18", "Hieromartyr Theodotus of Ancyra", O, "Innkeeper of Ancyra who sheltered persecuted Christians, gathered the martyrs' relics and was beheaded around 303.", "Innkeepers, hosts"),
    ("May 19", "Martyr Patricius, Bishop of Prusa", O, "Bishop of Prusa in Bithynia who was martyred in the early fourth century along with other Christians during the persecution of Diocletian.", "Bishops, the persecuted"),
    ("May 20", "Martyr Thalelaeus", O, "A physician of Cilicia who healed without payment and was martyred around 284. He is one of the Holy Unmercenaries and is invoked for healing.", "Physicians, the sick"),
    ("May 21", "Saints Constantine and Helen, Equals of the Apostles", O, "The emperor who ended the persecution of Christians and convened the Council of Nicaea, and his mother who found the True Cross in Jerusalem.", "Rulers, pilgrims, converts"),
    ("May 22", "Martyr Basiliscus of Comana", O, "Nephew of Saint Theodore the Recruit, martyred around 308 after praying for his persecutors. He is remembered for boldness of faith.", "Young people, the persecuted"),
    ("May 23", "Saint Michael, Bishop of Synada", O, "Bishop of Synada in Phrygia (d. 821) who defended the veneration of icons and was exiled by the iconoclast emperor.", "Defenders of icons"),
    ("May 24", "Venerable Simeon of the Wondrous Mountain", O, "A syrian monk (521-596) who lived on a pillar near Antioch for decades, praying for the afflicted and healing the sick.", "Hermits, the sick"),
    ("May 25", "The Third Finding of the Head of Saint John the Baptist", O, "The Church recalls the third discovery of the head of the Forerunner, whose relic was honoured and carried to Constantinople.", "Those who prepare the way of the Lord"),
    ("May 26", "The Holy Apostle Carpus of the Seventy", O, "A disciple of Saint Paul who hosted him at Troas and kept his cloak and books. He later served as bishop of Berea.", "Hosts, books and travellers"),
    ("May 28", "Venerable Nicetas of Chalcedon", O, "Monk and abbot of Chalcedon who endured exile for his stand against iconoclasm and died in 824.", "Confessors, defenders of icons"),
    ("May 29", "Martyr Theodosia of Constantinople", O, "A nun of Constantinople martyred around 729 for trying to prevent the removal of the icon of Christ from the Chalke Gate, an early act of resistance to iconoclasm.", "Defenders of icons, nuns"),
    ("May 30", "Venerable Isaac the Confessor", O, "Abbot of the Dalmatian monastery (d. 383) who was a confessor under Valens and a spiritual father to the Christian community of Constantinople.", "Confessors, abbots"),

    ("June 2", "Saint Nicephorus the Confessor", O, "Patriarch of Constantinople (c. 758-828) who defended holy icons and was exiled by the iconoclast emperor Leo V. He wrote a history of the Byzantine Empire.", "Defenders of icons, historians"),
    ("June 3", "Martyr Lucillian of Byzantium", O, "A pagan priest who converted to Christ in the third century and was martyred with four young men at Byzantium.", "Converts"),
    ("June 4", "Saint Metrophanes of Constantinople", O, "First bishop of Byzantium after the church's early days (d. c. 325), known as a pastor and for his role at the Council of Nicaea.", "Bishops, Constantinople"),
    ("June 8", "The Translation of the Relics of Great Martyr Theodore Stratelates", O, "The relics of Saint Theodore were moved to Constantinople and the faithful honoured them for the many healings that took place.", "Soldiers, the faithful"),
    ("June 10", "Hieromartyr Timothy of Prusa", O, "Bishop of Prusa in Bithynia, martyred in the fourth century. He is honoured as a steadfast shepherd of his flock.", "Bishops, shepherds"),
    ("June 12", "Venerable Onuphrius the Great", O, "Egyptian hermit of the fourth century who lived in the desert of the Thebaid in complete solitude for sixty years. Paphnutius met him shortly before his death.", "Hermits, weavers"),
    ("June 13", "Martyr Aquilina of Byblos", O, "A girl of twelve who was martyred in Phoenicia around 293 for refusing to renounce Christ. Her courage astonished the governor.", "Children, young women"),
    ("June 15", "The Holy Prophet Amos", O, "A shepherd of Tekoa and prophet of justice who called for righteousness and care of the poor. 'Let justice roll down like waters' is among his words.", "Shepherds, those who seek justice"),
    ("June 16", "Venerable Tikhon of Amathus", O, "Bishop of Amathus in Cyprus (d. c. 425) who was known for holiness and miracle-working and for his love of the poor.", "Bishops, gardeners"),
    ("June 17", "Martyrs Manuel, Sabel and Ishmael", O, "Three Persian ambassadors sent to Emperor Julian and martyred in 362 when they refused to deny Christ.", "Diplomats, those who stand for faith"),
    ("June 18", "Martyr Leontius of Tripoli", O, "Roman soldier martyred in Tripoli of Phoenicia around 73 with Hypatius and Theodulus for refusing to sacrifice to idols.", "Soldiers"),
    ("June 19", "The Holy Apostle Jude, Brother of the Lord", O, "Author of the New Testament letter who calls believers to contend for the faith once delivered to the saints. He is invoked in desperate causes.", "Hopeless causes, those who seek help"),
    ("June 20", "Hieromartyr Methodius of Patara", O, "Bishop and writer (d. 311) who defended the resurrection of the body and wrote the Symposium on virginity. He was martyred under Diocletian.", "Writers, bishops"),
    ("June 21", "Martyr Julian of Tarsus", O, "A young man of Cilicia who was martyred in the fourth century after enduring torture rather than deny Christ.", "Young people, the persecuted"),
    ("June 22", "Hieromartyr Eusebius of Samosata", O, "Bishop of Samosata (d. 379) who stood with Saint Basil against Arianism and was killed by a tile thrown from a rooftop while strengthening the faithful.", "Defenders of the faith, bishops"),
    ("June 23", "Martyr Agrippina of Rome", O, "A young Roman woman martyred around 253 for her faith. Her relics were later carried to Sicily and are widely venerated.", "Young women"),
    ("June 25", "Venerable Febronia of Nisibis", O, "Syrian abbess of the fourth century who endured imprisonment and torture under Diocletian and became a model of faith for the nuns of Nisibis.", "Nuns, women religious"),
    ("June 26", "Venerable David of Thessalonica", O, "Monk of the sixth century who lived three years in an almond tree in prayer and was known for wonder-working.", "Hermits, tree-dwellers"),
    ("June 30", "The Synaxis of the Twelve Holy Apostles", "all", "The Church honours all twelve apostles together, the first witnesses and heralds of the risen Christ. It is the final feast of the Apostles' Fast.", "The Church, all believers"),
]
